mod domain;

use domain::Money;

fn m(cents: i64) -> Money {
    Money { cents }
}

#[test]
fn adds_cents() {
    let sum = m(2).checked_add(m(3)).expect("sum should exist");
    assert_eq!(sum.cents, 5);
}

#[test]
fn overflow_returns_none() {
    assert!(m(i64::MAX).checked_add(m(1)).is_none());
    assert!(m(i64::MIN).checked_add(m(-1)).is_none());
}

